<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | <?= esc($formTitle) ?></title><?= view('partials/styles') ?></head>
<body><div class="app-shell"><?= view('partials/nav', ['active' => 'tasks']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Task management</p><h1><?= esc($formTitle) ?></h1><p class="subtitle">Complete the required fields before saving.</p></div></header><section class="panel" style="max-width:760px"><form method="post" action="<?= base_url($formAction) ?>" style="display:grid;gap:18px"><?php $errors = session()->getFlashdata('errors') ?? []; ?><?php if ($errors): ?><div style="color:#b42318;font-size:13px"><?php foreach ($errors as $message): ?><div><?= esc($message) ?></div><?php endforeach; ?></div><?php endif; ?><label>Title *<input name="title" value="<?= esc(old('title', $task['title'] ?? '')) ?>" required maxlength="150" style="display:block;width:100%;padding:12px;margin-top:6px;border:1px solid var(--line);border-radius:8px"></label><label>Task date *<input type="date" name="task_date" value="<?= esc(old('task_date', $task['task_date'] ?? date('Y-m-d'))) ?>" required style="display:block;width:100%;padding:12px;margin-top:6px;border:1px solid var(--line);border-radius:8px"></label><label>Description<textarea name="description" maxlength="1000" rows="5" style="display:block;width:100%;padding:12px;margin-top:6px;border:1px solid var(--line);border-radius:8px"><?= esc(old('description', $task['description'] ?? '')) ?></textarea></label><div><button class="button" type="submit" style="border:0;cursor:pointer">Save task</button> <a href="<?= base_url('tasks') ?>">Cancel</a></div></form></section></main></div></body></html>
